import {
  Group,
  Mesh,
  PlaneGeometry,
  BoxGeometry,
  Color,
  DirectionalLight,
  DoubleSide,
  RepeatWrapping,
  MeshPhysicalNodeMaterial,
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import { uv, mix, color as tslColor } from 'three/tsl';
import { gsap } from 'gsap';

const PALETTE = {
  background: '#0b0b10',
  surface: '#14141a',
  ink: '#16161d',
  paper: '#e8ecf2',
  accent: '#ff2a38',
};

const PLATE_W = 1.9;
const PLATE_H = 1.2;
const PITCH = 1.5;
const COUNT = 6;
const LOOP_RANGE = PITCH * COUNT; // 9.0
const COLUMN_X = 0.9;
const CAPTION_LOCAL_X = -1.6 - COLUMN_X;

function wrap(v, min, max) {
  const range = max - min;
  let r = (v - min) % range;
  if (r < 0) r += range;
  return r + min;
}

function setOpacity(obj, opacity) {
  if (!obj) return;
  obj.traverse((child) => {
    if (child.material) {
      const mats = Array.isArray(child.material) ? child.material : [child.material];
      mats.forEach((m) => {
        if (!m) return;
        m.transparent = true;
        m.opacity = opacity;
        m.needsUpdate = true;
      });
    }
  });
}

function disposeObject(obj) {
  if (!obj) return;
  obj.traverse((child) => {
    if (child.geometry) child.geometry.dispose();
    if (child.material) {
      const mats = Array.isArray(child.material) ? child.material : [child.material];
      mats.forEach((m) => {
        if (m.map) m.map.dispose();
        if (m.dispose) m.dispose();
      });
    }
  });
}

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = { ...PALETTE, ...(visualSpec.colors ?? config.colors ?? {}) };
  const gradientStops = colors.gradientStops ?? [
    { at: 0, hex: colors.background },
    { at: 1, hex: colors.surface },
  ];
  const stopA = gradientStops[0]?.hex ?? colors.background;
  const stopB = gradientStops[gradientStops.length - 1]?.hex ?? colors.surface;

  const items = config.textContent ?? visualSpec.textContent ?? [];
  const headlineItem = items.find((it) => it.role === 'headline');
  const captionItems = items.filter((it) => it.role === 'caption');
  const headlineText = headlineItem?.text ?? 'Inside the atelier';
  const captionTexts = [];
  for (let i = 0; i < COUNT; i++) {
    captionTexts.push(captionItems[i]?.text ?? '');
  }

  const root = new Group();
  root.name = 'loop-column-gallery';

  // ---------- backdrop ----------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({ side: DoubleSide });
  backdropMat.colorNode = mix(tslColor(stopA), tslColor(stopB), uv().y);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // ---------- lights (node-local, scene already provides ambient 0.6 + key 1.2) ----------
  const rimLight = new DirectionalLight(new Color(colors.accent), 0.7);
  rimLight.position.set(-2.2, 1.2, 2.4);
  root.add(rimLight);

  const fillLight = new DirectionalLight(new Color(colors.paper), 0.5);
  fillLight.position.set(2.0, 0.6, 1.8);
  root.add(fillLight);

  // ---------- headline ----------
  const headline = ctx.fontAtlas.createText(headlineText, {
    fontSize: 68,
    color: colors.paper,
    align: 'left',
  });
  headline.position.set(-1.6, 1.9, 0);
  root.add(headline);

  // ---------- column ----------
  const columnGroup = new Group();
  columnGroup.position.set(COLUMN_X, 0, 0);
  root.add(columnGroup);

  const baseTexturePromise = ctx.textureLoader.loadTexture(config.imageUrl);

  const plateGroups = [];
  const plateMeshes = [];
  const captionGroups = [];
  const clonedTextures = [];

  for (let i = 0; i < COUNT; i++) {
    const plateGroup = new Group();
    const baseY = (i - (COUNT - 1) / 2) * PITCH;
    plateGroup.userData.baseY = baseY;
    plateGroup.position.y = baseY;
    columnGroup.add(plateGroup);
    plateGroups.push(plateGroup);

    // bevel frame behind the plate
    const frameGeo = new BoxGeometry(PLATE_W + 0.06, PLATE_H + 0.06, 0.03);
    const frameMat = new MeshPhysicalNodeMaterial({
      color: new Color(colors.ink),
      roughness: 0.5,
      metalness: 0.5,
      clearcoat: 0.1,
    });
    const frame = new Mesh(frameGeo, frameMat);
    frame.position.z = -0.02;
    plateGroup.add(frame);

    // photograph plate
    const plateGeo = new PlaneGeometry(PLATE_W, PLATE_H);
    const plateMat = new MeshPhysicalNodeMaterial({
      roughness: 0.6,
      metalness: 0.1,
      clearcoat: 0.1,
      color: new Color().setScalar(0.92 + (i % 3) * 0.03),
    });
    const plate = new Mesh(plateGeo, plateMat);
    plate.position.z = 0;
    plateGroup.add(plate);
    plateMeshes.push(plate);

    // caption slot (world x lands at -1.6)
    const captionGroup = new Group();
    captionGroup.position.set(CAPTION_LOCAL_X, 0, 0.1);
    const captionText = ctx.fontAtlas.createText(captionTexts[i] || '', {
      fontSize: 18,
      color: colors.paper,
      align: 'left',
      letterSpacingPx: 1.5,
    });
    captionGroup.add(captionText);
    setOpacity(captionGroup, 0);
    plateGroup.add(captionGroup);
    captionGroups.push(captionGroup);
  }

  baseTexturePromise.then((tex) => {
    for (let i = 0; i < COUNT; i++) {
      const cloned = tex.clone();
      cloned.needsUpdate = true;
      cloned.wrapS = RepeatWrapping;
      cloned.wrapT = RepeatWrapping;
      cloned.repeat.set(1, 1);
      cloned.offset.set((i % 3) * 0.06, Math.floor(i / 3) * 0.05);
      clonedTextures.push(cloned);
      plateMeshes[i].material.map = cloned;
      plateMeshes[i].material.needsUpdate = true;
    }
  });

  // ---------- accent strip (tracks focused plate) ----------
  const accentGeo = new BoxGeometry(0.03, PLATE_H, 0.02);
  const accentMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    emissive: new Color(colors.accent),
    emissiveIntensity: 1.4,
    roughness: 0.4,
    metalness: 0.2,
  });
  const accentStrip = new Mesh(accentGeo, accentMat);
  accentStrip.position.set(COLUMN_X - PLATE_W / 2 - 0.02, 0, 0.05);
  root.add(accentStrip);

  // ---------- scroll-driven loop motion ----------
  let scrollTarget = 0;
  let scrollCurrent = 0;
  let focusedIndex = -1;
  let settleTimer = null;
  const activeTweens = [];

  function applyFocusTransition(newFocus, wrappedYs) {
    if (newFocus === focusedIndex) return;
    const prevFocus = focusedIndex;
    focusedIndex = newFocus;

    if (prevFocus >= 0) {
      const t1 = gsap.to(plateGroups[prevFocus].scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.35,
        ease: 'power2.out',
      });
      const capMat = [];
      captionGroups[prevFocus].traverse((c) => c.material && capMat.push(c.material));
      const t2 = gsap.to(capMat, { opacity: 0, duration: 0.3, ease: 'power2.out' });
      activeTweens.push(t1, t2);
    }

    const t3 = gsap.to(plateGroups[newFocus].scale, {
      x: 1.06,
      y: 1.06,
      z: 1.06,
      duration: 0.35,
      ease: 'power2.out',
    });
    const capMat2 = [];
    captionGroups[newFocus].traverse((c) => c.material && capMat2.push(c.material));
    capMat2.forEach((m) => {
      m.transparent = true;
    });
    const t4 = gsap.to(capMat2, { opacity: 1, duration: 0.5, ease: 'power2.out' });
    activeTweens.push(t3, t4);
  }

  function update() {
    scrollCurrent += (scrollTarget - scrollCurrent) * 0.12;

    const wrappedYs = [];
    let bestIdx = 0;
    let bestDist = Infinity;

    for (let i = 0; i < COUNT; i++) {
      const w = wrap(plateGroups[i].userData.baseY - scrollCurrent, -LOOP_RANGE / 2, LOOP_RANGE / 2);
      plateGroups[i].position.y = w;
      wrappedYs.push(w);
      const dist = Math.abs(w);
      if (dist < bestDist) {
        bestDist = dist;
        bestIdx = i;
      }
    }

    applyFocusTransition(bestIdx, wrappedYs);
    accentStrip.position.y = wrappedYs[focusedIndex] ?? 0;
  }

  // initial instant layout (no tween on first frame)
  update();

  gsap.ticker.add(update);

  // ---------- cinematic primitives ----------
  const primitiveResults = [];
  const cinematicPrimitives = config.cinematicPrimitives ?? [];
  for (const primitive of cinematicPrimitives) {
    const applyFn = ctx.primitives?.[primitive.name];
    if (typeof applyFn === 'function') {
      const result = applyFn(root, primitive.params ?? {});
      if (result) primitiveResults.push(result);
    }
  }

  // ---------- interaction handlers ----------
  root.userData.handlers = {
    scroll: (payload) => {
      const delta =
        typeof payload === 'number'
          ? payload
          : payload?.delta ?? payload?.deltaY ?? payload?.deltaScroll ?? 0;
      scrollTarget += delta * 1.5;

      if (settleTimer) clearTimeout(settleTimer);
      settleTimer = setTimeout(() => {
        scrollTarget = Math.round(scrollTarget / PITCH) * PITCH;
      }, 220);
    },
  };

  // ---------- cleanup ----------
  root.userData.cleanup = () => {
    gsap.ticker.remove(update);
    if (settleTimer) clearTimeout(settleTimer);
    activeTweens.forEach((t) => t.kill());
    gsap.killTweensOf(plateGroups.map((g) => g.scale));
    captionGroups.forEach((cg) => {
      cg.traverse((c) => {
        if (c.material) gsap.killTweensOf(c.material);
      });
    });

    primitiveResults.forEach((r) => {
      try {
        r.timeline && r.timeline.kill();
        r.cleanup && r.cleanup();
      } catch (e) {
        /* noop */
      }
    });

    clonedTextures.forEach((t) => t.dispose());
    disposeObject(root);
  };

  return root;
}
